function validate([ranges, left, right]) {
  if (!Array.isArray(ranges) || ranges.length < 1 || ranges.length > 50) return 'ranges needs 1 to 50 intervals.';
  for (const range of ranges) {
    if (!Array.isArray(range) || range.length !== 2) return 'Each interval is a [start, end] pair.';
    const [start, end] = range;
    if (!Number.isInteger(start) || !Number.isInteger(end) || start < 1 || end > 50 || start > end) return 'Each interval needs 1 <= start <= end <= 50.';
  }
  if (!Number.isInteger(left) || !Number.isInteger(right) || left < 1 || right > 50 || left > right) return 'left and right need 1 <= left <= right <= 50.';
  return null;
}

