function generate(rand, size) {
  const large = size === 'large';
  const top = large ? 50 : 12;
  const count = large ? 50 : 1 + Math.floor(rand() * 5);
  const maxLength = large ? 1 + Math.floor(rand() * 4) : 1 + Math.floor(rand() * 5);
  const ranges = Array.from({ length: count }, () => {
    const start = 1 + Math.floor(rand() * top);
    const end = Math.min(top, start + Math.floor(rand() * maxLength));
    return [start, end];
  });
  const a = 1 + Math.floor(rand() * top);
  const b = 1 + Math.floor(rand() * top);
  return [ranges, Math.min(a, b), Math.max(a, b)];
}
